import{_ as t,o as a,c as o,ai as n}from"./chunks/framework.DQi1ytmF.js";const u=JSON.parse('{"title":"Text contrast, proven without a browser","description":"","frontmatter":{},"headers":[],"relativePath":"guide/style/contrast.md","filePath":"guide/style/contrast.md"}'),s={name:"guide/style/contrast.md"};function i(r,e,d,l,h,c){return a(),o("div",null,[...e[0]||(e[0]=[n(`<div style="display:none;" hidden data-nosnippet>Are you an LLM? You can read better optimized documentation at /craft/guide/style/contrast.md for this page in Markdown format</div><h1 id="text-contrast-proven-without-a-browser" tabindex="-1">Text contrast, proven without a browser <a class="header-anchor" href="#text-contrast-proven-without-a-browser" aria-label="Permalink to &quot;Text contrast, proven without a browser&quot;">​</a></h1><p><code>npm run style:check</code> reads your sheets and your templates and answers one question, for every element it can prove holds text, in every state your axes can produce:</p><blockquote><p>is this text readable on the background it is actually painted on?</p></blockquote><p>It is WCAG 2.2 §1.4.3 level AA — <code>4.5:1</code> for normal text, <code>3:1</code> for large text — and it needs no browser, no screenshot and no Playwright run.</p><div class="warning custom-block"><p class="custom-block-title">What this is not</p><p>This proves <strong>text contrast</strong>, in a declared subset of CSS. It is not an accessibility audit, and a green run is not a claim that your application is accessible. Focus order, names, roles, motion, target size and everything else are elsewhere. Read <a href="#the-coverage-contract">the coverage contract</a> before you put a badge on it.</p></div><h2 id="running-it" tabindex="-1">Running it <a class="header-anchor" href="#running-it" aria-label="Permalink to &quot;Running it&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> style:check</span></span></code></pre></div><p>In a project generated with typed CSS this is already wired: it builds once so the style plugin writes <code>.craft/style-graph.json</code>, then analyses that dump together with your TypeScript program.</p><p>By hand, on an existing project:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> craft-graph</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --style-contrast</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --style-dump</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .craft/style-graph.json</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tsconfig.app.json</span></span></code></pre></div><p><code>--json</code> gives a stable machine-readable report for CI. Two runs on unchanged sources produce byte-identical output.</p><p>Unlike <code>--style-matrix</code> and <code>--style-debt</code>, this command <strong>does</strong> build the TypeScript program. It has to: a contrast proof needs to know which element carries which class and what sits above it, and no style dump has ever seen a template.</p><h2 id="reading-a-failure" tabindex="-1">Reading a failure <a class="header-anchor" href="#reading-a-failure" aria-label="Permalink to &quot;Reading a failure&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>contrast/fail</span></span>
<span class="line"><span>route: /checkout</span></span>
<span class="line"><span>component: SubmitButton</span></span>
<span class="line"><span>element: button.root</span></span>
<span class="line"><span>scenario: interaction.hover=active+tone=warning</span></span>
<span class="line"><span>foreground: ui.text.onAccent #ffffff (dsButton-root → --dsButton-ink (initial))</span></span>
<span class="line"><span>background: ui.accent.warning.dark #f5b544 (button.root: dsButton-root → --dsButton-bg)</span></span>
<span class="line"><span>font: 14px / 600 (normal text)</span></span>
<span class="line"><span>ratio: 1.81:1</span></span>
<span class="line"><span>required: 4.5:1</span></span></code></pre></div><p>Every line is there because a report missing it sends you to the wrong file:</p><ul><li><strong>scenario</strong> — the exact combination. Not &quot;the warning button&quot;: the warning button <em>under the pointer</em>, which is often the only failing one.</li><li><strong>foreground / background</strong> — the token name first, then the value, then the chain that produced it. <code>ui.accent.warning.dark</code> tells you which token to change; <code>dsButton-root → --dsButton-bg</code> tells you which rule put it there.</li><li><strong>font</strong> — with the threshold it earned. See <a href="#which-threshold-applies">large text</a>.</li></ul><p>Rows that resolve to the same answer are folded together and list the scenarios they stand for under <code>also in:</code>, so a five-tone button does not print five identical lines.</p><h2 id="the-two-halves-and-why-only-one-of-them-fails-a-build" tabindex="-1">The two halves, and why only one of them fails a build <a class="header-anchor" href="#the-two-halves-and-why-only-one-of-them-fails-a-build" aria-label="Permalink to &quot;The two halves, and why only one of them fails a build&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th><code>--palette-contrast</code></th><th><code>--style-contrast</code></th></tr></thead><tbody><tr><td>reads</td><td>the dump alone</td><td>the dump <strong>and</strong> the templates</td></tr><tr><td>answers</td><td>every pair your palette can express</td><td>every pair an element is actually painted in</td></tr><tr><td>verdict</td><td>informative</td><td><strong>blocking</strong></td></tr></tbody></table><p>A palette of twenty tokens has hundreds of pairs and an application renders a few dozen of them. Failing a build on <code>ui.text.onAccent</code> over <code>ui.surface.page</code> — white on white, and a combination no element uses — trains people to switch the check off, and takes the real failures with it.</p><p>So the matrix is a table you read while designing, and the analysis is the gate. When you pass the analysis&#39;s results to <code>paletteContrastMatrix</code>, each pair also gets a <code>usedBy</code> list of the elements that render it; without them the field is <strong>absent</strong> rather than empty, because &quot;nobody looked&quot; and &quot;the analysis looked and found nowhere&quot; are different answers.</p><h2 id="which-threshold-applies" tabindex="-1">Which threshold applies <a class="header-anchor" href="#which-threshold-applies" aria-label="Permalink to &quot;Which threshold applies&quot;">​</a></h2><ul><li>large if <code>font-size &gt;= 24px</code>;</li><li>large if <code>font-size &gt;= 18.5px</code> <strong>and</strong> the weight is at least <code>700</code>;</li><li>normal otherwise.</li></ul><p>Two consequences worth knowing before you argue with a report:</p><ul><li><code>text.lg</code> is <code>1.125rem</code> — <strong>18px</strong> — so a bold title at that size is <em>normal</em> text and needs <code>4.5:1</code>. It misses the large threshold by half a pixel.</li><li><code>600</code> is not bold. WCAG says &quot;bold&quot; without a number and CSS says bold is 700; reading <code>600</code> as bold would lower a threshold on an ambiguity, which is the wrong side to err on.</li></ul><p><code>rem</code> becomes pixels against a 16px root. If your page sets a different root size outside CraftTS, say so — nothing in the dump can know.</p><p>The ratio is <strong>never rounded before it is compared</strong>. <code>4.4999:1</code> fails a 4.5 threshold, even though the report prints it as <code>4.49:1</code>.</p><h2 id="how-colour-is-resolved" tabindex="-1">How colour is resolved <a class="header-anchor" href="#how-colour-is-resolved" aria-label="Permalink to &quot;How colour is resolved&quot;">​</a></h2><h3 id="color-is-inherited" tabindex="-1"><code>color</code> is inherited <a class="header-anchor" href="#color-is-inherited" aria-label="Permalink to &quot;\`color\` is inherited&quot;">​</a></h3><p>The analysis walks the element&#39;s ancestor chain outside-in, exactly as the cascade does. A paragraph that sets no colour of its own takes the one from its card, or from the theme wrapper above it.</p><h3 id="the-background-is-the-first-opaque-thing-underneath" tabindex="-1">The background is the first opaque thing underneath <a class="header-anchor" href="#the-background-is-the-first-opaque-thing-underneath" aria-label="Permalink to &quot;The background is the first opaque thing underneath&quot;">​</a></h3><p>Starting at the element and walking outwards:</p><ul><li>an element that paints nothing is transparent, and the search continues;</li><li>the first opaque colour wins;</li><li>an element that paints something the model cannot read — an image, a semi-transparent fill, anything behind an <code>opacity</code> — <strong>stops</strong> the search and produces <code>indeterminate</code>, because whatever is behind it is no longer what the text is composited against.</li></ul><p>If nothing in the chain paints, that is <code>unknown-background</code>. It is not &quot;assume white&quot;: a white assumption is right on one theme and wrong on the other.</p><h3 id="variables-resolve-the-way-property-says-they-do" tabindex="-1">Variables resolve the way <code>@property</code> says they do <a class="header-anchor" href="#variables-resolve-the-way-property-says-they-do" aria-label="Permalink to &quot;Variables resolve the way \`@property\` says they do&quot;">​</a></h3><ul><li>a registered variable nobody wrote resolves to its <strong>registered initial value</strong>, not to the <code>var()</code> fallback;</li><li><code>inherits: false</code> really does not cross into a child — a theme variable set on a wrapper reaches the button, a component variable does not.</li></ul><p>That last one is the trap the design system is full of, and getting it wrong would prove the wrong colour for every component under a themed wrapper.</p><h3 id="the-cascade-is-replayed-not-approximated" tabindex="-1">The cascade is replayed, not approximated <a class="header-anchor" href="#the-cascade-is-replayed-not-approximated" aria-label="Permalink to &quot;The cascade is replayed, not approximated&quot;">​</a></h3><p>Three tie-breaks, in the browser&#39;s order:</p><ol><li><strong>Layer.</strong> Unconditional atoms land in <code>components</code>, conditional ones in <code>variants</code>, so every variant beats every base rule.</li><li><strong>Specificity</strong>, inside <code>variants</code>. <code>&amp;[data-tone=&#39;warning&#39;]:hover</code> has one more selector fragment than <code>&amp;[data-tone=&#39;warning&#39;]</code>, so the hovered fill wins — whatever the source order. A media query contributes nothing.</li><li><strong>Source order</strong>, last, which is atomic class-name order because that is how the emitter sorts the layer.</li></ol><p>Getting the second wrong is the interesting failure: a solver would resolve a tone-plus-hover button to its resting fill and report <code>pass</code> on the state that fails.</p><h2 id="hover-is-an-axis" tabindex="-1">Hover is an axis <a class="header-anchor" href="#hover-is-an-axis" aria-label="Permalink to &quot;Hover is an axis&quot;">​</a></h2><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">when</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(tone.warning, [</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  set</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(buttonVars.bg, ui.accent.warning),</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  when</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(interaction.hover, [</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">set</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(buttonVars.bg, ui.accent.warningHover)]),</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]);</span></span></code></pre></div><p><code>interaction.hover</code> emits the same <code>:hover</code> rule a hand-written selector would. What it adds is that the point lands in the class&#39;s variant contract — so the visual matrix captures the hovered state, and this analysis crosses the colours it writes with the text that sits on them.</p><p>A <code>:hover</code> typed into a string is invisible to both. That is how a button ends up readable at rest and unreadable under the pointer: the one state nobody screenshots. The <code>prefer-hover-axis</code> lint rule refuses it.</p><p>The axis carries its own driver (<code>{ kind: &#39;selfState&#39;, state: &#39;hover&#39; }</code>), so a capture of the hovered state is something a harness can actually produce. <code>applyScenario</code> asks the page to move a real pointer and throws if it cannot — dispatching a <code>mouseover</code> event would fire listeners and leave the pseudo-class untouched, producing a screenshot of the base state that passes forever.</p><p>The cost is real and it is a decision: hover doubled the demo button&#39;s matrix from 18 scenarios to 36. That is why the axis has to be in the sheet&#39;s budget.</p><h2 id="naming-your-palette" tabindex="-1">Naming your palette <a class="header-anchor" href="#naming-your-palette" aria-label="Permalink to &quot;Naming your palette&quot;">​</a></h2><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> ui</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> definePalette</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;ui&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  text: { onAccent: { light: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;#ffffff&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, dark: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;#0b0d11&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> } },</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  accent: { warning: { light: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;#8a5a00&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, dark: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;#f5b544&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> } },</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">});</span></span></code></pre></div><p>The name travels with every colour, through variables and <code>darkOf()</code>, all the way into the report. <code>definePalette(spec)</code> without a name still works and still carries the group and the token — you get <code>(unnamed).accent.warning</code>, which points at the right entry and asks to be named.</p><p>Write hovered and pressed fills as <strong>tokens</strong>, not as a <code>darken()</code> at the use site. A function hides the resulting colour from the palette, and the palette is where the contrast question gets settled once instead of per component.</p><h2 id="the-coverage-contract" tabindex="-1">The coverage contract <a class="header-anchor" href="#the-coverage-contract" aria-label="Permalink to &quot;The coverage contract&quot;">​</a></h2><h3 id="covered-in-v1" tabindex="-1">Covered in v1 <a class="header-anchor" href="#covered-in-v1" aria-label="Permalink to &quot;Covered in v1&quot;">​</a></h3><ul><li>opaque colours in hexadecimal or <code>rgb()</code>/<code>rgba()</code>;</li><li>inherited <code>color</code>;</li><li><code>background-color</code>, local or seen through transparent ancestors;</li><li>CraftTS variables declared with <code>cssVars()</code>, their initial values, their conditional writes and their <code>var()</code> fallbacks;</li><li>constant classes from <code>craftStyles()</code>;</li><li>light and dark themes;</li><li>every finite state and size axis, <code>interaction.hover</code> included;</li><li>static and dynamic text, wherever the element can be proven to hold text;</li><li>a component evaluated once per surface it is rendered on.</li></ul><h3 id="not-covered-in-v1" tabindex="-1">Not covered in v1 <a class="header-anchor" href="#not-covered-in-v1" aria-label="Permalink to &quot;Not covered in v1&quot;">​</a></h3><p>Each of these produces <code>indeterminate</code> with its reason — never a pass.</p><ul><li>images and gradients behind text;</li><li><code>canvas</code>, text inside SVG, generated pseudo-element content;</li><li><code>filter</code>, <code>backdrop-filter</code>, <code>mix-blend-mode</code>, and any <code>opacity</code> below 1;</li><li>semi-transparent colours, which would need compositing;</li><li>CSS expressions the DSL does not model;</li><li>colours computed from runtime data that is not a finite set;</li><li>external stylesheets and inline styles outside CraftTS;</li><li>CJK metrics and unusual font geometry — the size in CSS pixels is not the size on screen, and the large-text convention assumes latin faces.</li></ul><h3 id="what-indeterminate-means-and-why-it-fails-by-default" tabindex="-1">What <code>indeterminate</code> means, and why it fails by default <a class="header-anchor" href="#what-indeterminate-means-and-why-it-fails-by-default" aria-label="Permalink to &quot;What \`indeterminate\` means, and why it fails by default&quot;">​</a></h3><table tabindex="0"><thead><tr><th>reason</th><th>what happened</th></tr></thead><tbody><tr><td><code>unknown-foreground</code></td><td>nothing readable sets the text colour</td></tr><tr><td><code>unknown-background</code></td><td>nothing in the chain paints an opaque surface</td></tr><tr><td><code>unknown-font-size</code></td><td>the size is not a length this can turn into pixels</td></tr><tr><td><code>unsupported-background</code></td><td>an image, a gradient, a blend, or an alpha</td></tr><tr><td><code>dynamic-style</code></td><td>the class is assembled at runtime</td></tr><tr><td><code>external-style</code></td><td>the styles come from outside CraftTS</td></tr><tr><td><code>incomplete-render-context</code></td><td>the component is rendered somewhere unanalysed</td></tr></tbody></table><p><strong>Indeterminate results fail the run.</strong> <code>--allow-indeterminate</code> downgrades them to warnings, and you have to type it. A check whose default treats &quot;I could not tell&quot; as &quot;fine&quot; reports a clean bill on the half of the application it understood — and that half is exactly where the gradients and the runtime colours live.</p><p>A report with <strong>no violations and open indeterminates is not a proof.</strong> The summary prints all three counts for that reason:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Text contrast: 41 pass, 0 fail, 3 indeterminate (44 checked).</span></span></code></pre></div><p>Zero checked is not a pass either, and the tool says so: it nearly always means the dump and the program describe different applications.</p><h2 id="fixing-a-violation" tabindex="-1">Fixing a violation <a class="header-anchor" href="#fixing-a-violation" aria-label="Permalink to &quot;Fixing a violation&quot;">​</a></h2><ol><li><strong>Read the scenario.</strong> If only the hovered or only the dark row fails, the fix belongs to that one rule, not to the token everything uses.</li><li><strong>Read the token names.</strong> A pair that fails in several places is a palette decision — change the token once, and <code>usedBy</code> tells you what moves.</li><li><strong>Change the token, not the call site.</strong> A local override is a colour the palette no longer describes, and the next component repeats the bug.</li><li><strong>If the text is genuinely large</strong>, check that the sheet says so. 18px bold is normal text; 22px bold is large.</li><li><strong>Re-run.</strong> The report is deterministic, so a diff of two JSON runs shows exactly what your change moved.</li></ol><h2 id="clearing-an-indeterminate" tabindex="-1">Clearing an indeterminate <a class="header-anchor" href="#clearing-an-indeterminate" aria-label="Permalink to &quot;Clearing an indeterminate&quot;">​</a></h2><p>You have three honest moves, and inventing a colour is not one of them.</p><ul><li><strong>Bring the surface into the model.</strong> A <code>background-color</code> set in raw CSS is the common case; <code>no-unmodelled-text-color</code> points at it.</li><li><strong>Give the text a surface it can be measured against.</strong> Text over a hero image has no ratio because it has no single background — put it on a panel, or accept that it cannot be proven.</li><li><strong>Declare the surface uncovered.</strong> Add its path to the <code>no-unmodelled-text-color</code> rule&#39;s <code>uncovered</code> option. The gap is then counted as a gap rather than mistaken for a proof, which is the whole point.</li></ul><h2 id="migrating-an-existing-project" tabindex="-1">Migrating an existing project <a class="header-anchor" href="#migrating-an-existing-project" aria-label="Permalink to &quot;Migrating an existing project&quot;">​</a></h2><ol><li>Name your palette: <code>definePalette(&#39;ui&#39;, spec)</code>. Nothing else changes.</li><li>Turn hand-written <code>:hover</code> rules into <code>when(interaction.hover, …)</code> and add <code>interaction</code> to those sheets&#39; budgets. <code>prefer-hover-axis</code> finds them.</li><li>Add <code>dumpPath: &#39;.craft/style-graph.json&#39;</code> to <code>craftStyle()</code> in <code>vite.config.ts</code>.</li><li>Replace <code>style:check</code> with a build followed by <code>craft-graph --style-contrast</code>.</li><li>Run it with <code>--allow-indeterminate</code> <strong>once</strong>, to see the size of the gap.</li><li>Close the gaps, or declare them uncovered, and drop the flag. Leaving it on permanently is the same as not having the check.</li></ol>`,71)])])}const g=t(s,[["render",i]]);export{u as __pageData,g as default};
